import pathlib,json,copy,yaml,re
class Strict(yaml.SafeLoader):pass
def mapping(loader,node,deep=False):
 loader.flatten_mapping(node); out={}
 for k,v in node.value:
  key=loader.construct_object(k,deep=deep)
  if key in out:raise ValueError('duplicate key')
  out[key]=loader.construct_object(v,deep=deep)
 return out
Strict.add_constructor(yaml.resolver.BaseResolver.DEFAULT_MAPPING_TAG,mapping)
def load(name):return yaml.load(pathlib.Path(name).read_text(encoding='utf-8'),Loader=Strict)

BASE={'global': {'resolve_timeout': '5m'}, 'route': {'receiver': 'default', 'group_by': ['alertname', 'cluster'], 'group_wait': '30s', 'group_interval': '5m', 'repeat_interval': '4h', 'matchers': ['severity="critical"'], 'routes': [{'receiver': 'critical', 'matchers': ['severity="critical"']}]}, 'receivers': [{'name': 'default', 'webhook_configs': [{'url': 'https://hooks.example.test/default', 'send_resolved': True}]}, {'name': 'critical', 'webhook_configs': [{'url': 'https://hooks.example.test/critical', 'send_resolved': True}]}]}
d=load("alertmanager.yaml")
b=copy.deepcopy(BASE)
assert 'matchers' not in d['route'] and d['route']['receiver']=='default'
b['route'].pop('matchers');assert d==b

